cd /Users/logan/.claude/projects/-Users-logan/
F=56452f88-4aa9-43d4-9109-482212602d2c.jsonl
LN=$(grep -n -i -e 'king for a day' -e 'youngns' -e 'bite-sized' -e 'packs a punch' -e 'claude corp' "$F" | head -1 | cut -d: -f1)
echo "hit on jsonl line: $LN"
echo "===== role + text of that line (and the 2 lines around it) ====="
for n in $((LN-2)) $((LN-1)) $LN $((LN+1)); do
  [ "$n" -lt 1 ] && continue
  role=$(sed -n "${n}p" "$F" | python3 -c "import sys,json; d=json.load(sys.stdin); m=d.get('message',{}); print(d.get('type'),'/',m.get('role') if isinstance(m,dict) else '')" 2>/dev/null)
  echo "--- jsonl line $n  [$role] ---"
  sed -n "${n}p" "$F" | python3 -c "
import sys,json
d=json.load(sys.stdin)
m=d.get('message',{})
c=m.get('content') if isinstance(m,dict) else None
def show(t): print(t[:1600])
if isinstance(c,str): show(c)
elif isinstance(c,list):
    for b in c:
        if isinstance(b,dict):
            if b.get('type')=='text': show(b['text'])
            elif b.get('type')=='thinking': print('[thinking]',b.get('thinking','')[:400])
            elif b.get('type')=='tool_result':
                cc=b.get('content'); 
                if isinstance(cc,list):
                    for x in cc:
                        if isinstance(x,dict) and x.get('type')=='text': print('[tool_result]',x['text'][:1200])
                else: print('[tool_result]',str(cc)[:1200])
            elif b.get('type')=='tool_use': print('[tool_use]',b.get('name'),str(b.get('input'))[:400])
" 2>/dev/null
done

