for LN in 1822 1825 1828 1830; do
  meta=$(sed -n "${LN}p" "$F" | python3 -c "import sys,json; d=json.load(sys.stdin); m=d.get('message',{}); print(d.get('type'),'/',(m.get('role') if isinstance(m,dict) else ''))" 2>/dev/null)
  echo "=================== line $LN  [$meta] ==================="
  sed -n "${LN}p" "$F" | python3 -c "
import sys,json
d=json.load(sys.stdin); m=d.get('message',{}); c=m.get('content') if isinstance(m,dict) else None
def show(t,tag=''): print((tag+' ' if tag else '')+t[:2200])
if isinstance(c,str): show(c)
elif isinstance(c,list):
    for b in c:
        if not isinstance(b,dict): continue
        t=b.get('type')
        if t=='text': show(b['text'])
        elif t=='thinking': show(b.get('thinking',''),'[thinking]')
        elif t=='tool_use': show(str(b.get('input',{}).get('command',b.get('input'))),'[tool_use '+str(b.get('name'))+']')
        elif t=='tool_result':
            cc=b.get('content')
            if isinstance(cc,list):
                for x in cc:
                    if isinstance(x,dict) and x.get('type')=='text': show(x['text'],'[tool_result]')
            else: show(str(cc),'[tool_result]')
" 2>/dev/null
  echo
done
